import{_ as i,o as a,c as n,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Performance Meeting 2022-01-13","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-01-13","date":"2022-01-13T00:00:00.000Z","updated":"2022-01-18T00:00:00.000Z","tags":["Ceph性能","分布式存储","代码审查","Quincy版本","性能测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-01-13.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-01-13.md","lastUpdated":1780460162000}'),r={name:"posts/2022/Ceph_Performance_Meeting_2022-01-13.md"};function l(o,e,s,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[t('<p>本次会议主要讨论了Ceph分布式存储系统的性能优化和更新，以下为会议的主要内容：</p><h3 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h3><ol><li><p><strong>PR更新与合并情况</strong></p><ul><li><strong>RGW Zipper PR</strong>: 修复了RGW在Age Bidding测试中的性能问题。</li><li><strong>TTL Cache Implementation PR</strong>: 已合并，需进一步测试。</li><li><strong>Primary Balance PR</strong>: 代码重构，简化了计算PG Up Maps的代码。</li><li><strong>Fine Grain Locking PR</strong>: 合并后显示性能优势，但需更多测试验证。</li><li><strong>Age Binning PR</strong>: 多年未解决的PR，合并后虽未显示显著性能提升，但提供了更细粒度的缓存控制和更好的缓存项年龄信息。</li></ul></li><li><p><strong>其他PR更新</strong></p><ul><li><strong>Onode Binning Shardstrimming PR</strong>: 涉及Onode的Binning和Shardstrimming处理，以及Adam关于Onode引用计数器和固定的PR，均因过时被关闭。</li><li><strong>Auto Tuning of MDS Cache Memory PR</strong>: 因长时间未更新被关闭，讨论中提到可能使用优先级缓存来解决RSS内存使用的问题。</li></ul></li><li><p><strong>性能测试计划</strong></p><ul><li>讨论了即将到来的Quincy版本的性能测试计划，包括使用Mako进行大规模集群测试，涉及RBD、RGW、iSCSI、NBD等不同工作负载和设备。</li><li>特别提到了恢复测试的改进，由Sridhar提交的新恢复测试方法，创建了两个独立的池和图像，以更好地模拟实际恢复过程。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>确认了Quincy版本的性能测试计划。</li><li>关闭了多个过时的PR。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>继续进行Quincy版本的性能测试，特别是关注恢复测试的新方法。</li><li>确保所有关键PR得到适当的审查和测试，以准备Quincy版本的发布。</li></ul><h3 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h3><ul><li>会议由主持人主持，参会人员包括开发团队成员和其他相关人员。</li></ul><h3 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h3><ul><li>会议中提到的具体PR编号和详细技术讨论未在此纪要中列出，具体内容可参考会议录音或相关代码仓库。</li></ul>',11)])])}const u=i(r,[["render",l]]);export{p as __pageData,u as default};
